export type BotActivity = {
    automationFailed: boolean;
    activeSessions: number;
    runningChannels: number;
    enabledAutomations: number;
};

export type Bot = {
    /**
     * The bot ID.
     */
    readonly id?: string;
    /**
     * Activity counts returned by GET /api/bots.
     */
    activity?: BotActivity;
    /**
     * The bot name. Trim spaces before validation.
     */
    name: string;
    provider: string;
    /**
     * Empty when no model is chosen.
     */
    modelId: string;
    thinkingLevel: ThinkingLevel;
    fallbackProvider: string;
    /**
     * Empty when no fallback model is chosen. Needs a model.
     */
    fallbackModelId: string;
    instructions: string;
    /**
     * Empty means the built-in Local Runner.
     */
    runnerId: string;
    /**
     * Archive time in Unix milliseconds. Absent for an active bot.
     */
    readonly archivedAt?: number;
};

export type BotInput = {
    /**
     * The bot name. Trim spaces before validation.
     */
    name: string;
    provider: string;
    /**
     * Empty when no model is chosen.
     */
    modelId: string;
    thinkingLevel: ThinkingLevel;
    fallbackProvider?: string;
    /**
     * Empty when no fallback model is chosen. Needs a model.
     */
    fallbackModelId?: string;
    instructions?: string;
    /**
     * Empty or "local" selects the built-in Local Runner.
     */
    runnerId?: string;
};

export type CreateBotInput = {
    /**
     * The bot name. Trim spaces before validation.
     */
    name: string;
    provider?: string;
    /**
     * Omitted copies the default bot's model. Empty chooses no model.
     */
    modelId?: string;
    thinkingLevel?: ThinkingLevel;
    fallbackProvider?: string;
    /**
     * Omitted copies the default bot's fallback model. Empty chooses none.
     */
    fallbackModelId?: string;
    instructions?: string;
    /**
     * Omitted copies the default bot's Runner. Empty or "local" selects the built-in Local Runner.
     */
    runnerId?: string;
};

/**
 * pi-ai's ModelThinkingLevel. pi-ai sends the nearest level that the model supports.
 *
 */
export type ThinkingLevel = 'off' | 'minimal' | 'low' | 'medium' | 'high' | 'xhigh' | 'max';

export type Provider = {
    id: string;
    name: string;
    /**
     * Empty for a built-in provider.
     */
    api: string;
    baseUrl: string;
    keySet: boolean;
    /**
     * The enabled model IDs; empty enables all models that the endpoint lists.
     */
    models: Array<string>;
    /**
     * The number of models in the catalog for this provider.
     */
    modelCount?: number;
    /**
     * Why the engine could not list this provider's models.
     */
    error?: string;
};

export type ProviderInput = {
    api: string;
    name?: string;
    baseUrl?: string;
    /**
     * Write-only. Empty keeps the saved key.
     */
    apiKey?: string;
    /**
     * The enabled model IDs. Empty enables all models that the endpoint lists.
     *
     */
    models?: Array<string>;
};

export type ProviderModelsInput = {
    /**
     * A saved custom provider whose key to use when apiKey is empty.
     */
    providerId?: string;
    api: string;
    baseUrl: string;
    /**
     * Write-only.
     */
    apiKey?: string;
};

export type ProviderModelList = {
    models: Array<ProviderModel>;
};

export type ProviderModel = {
    id: string;
    name: string;
};

export type ProviderInfo = {
    id: string;
    name: string;
    source?: string;
};

export type ModelList = {
    models: Array<Model>;
};

export type Model = {
    provider: string;
    id: string;
    name: string;
    /**
     * pi-ai's Model.reasoning. False means the model does not think.
     */
    reasoning: boolean;
    /**
     * pi-ai's Model.input.
     */
    input: Array<'text' | 'image'>;
    /**
     * pi-ai's getSupportedThinkingLevels(model).
     */
    thinkingLevels: Array<ThinkingLevel>;
};

export type VaultEntry = {
    name: string;
    scope: IntegrationScope;
    updatedAt: string;
};

export type SharedIntegrations = {
    skills: Array<Skill>;
    /**
     * Stored declarations with no tools and state idle or disabled.
     */
    servers: Array<McpServer>;
    /**
     * Skill scan errors and warnings.
     */
    errors: Array<string>;
};

export type BotIntegrations = {
    /**
     * The .bots directories, from wide to narrow. Each can hold skills/. Two levels can have the same directory.
     *
     */
    levels: Array<{
        scope: IntegrationScope;
        dir: string;
    }>;
    /**
     * Current disk declarations; skills are read before each model request.
     */
    skills: Array<Skill>;
    /**
     * Loaded servers, or idle declarations before the bot opens.
     */
    servers: Array<McpServer>;
    warnings: Array<string>;
    /**
     * Invalid configuration prevents MCP startup and reload.
     */
    errors: Array<string>;
    /**
     * Extension files, vault entries, shell rc files, or 1Password settings changed after the bot loaded. dex reloads the bot when all bots are idle and the configuration is valid.
     *
     */
    reloadPending: boolean;
};

/**
 * Shared across dex or scoped to one bot.
 */
export type IntegrationScope = 'dex' | 'agent';

export type Skill = {
    name: string;
    description: string;
    /**
     * A file level, or project for .agents/skills under the bot workspace. The prompt reads the project level under the session's cwd.
     *
     */
    scope: 'dex' | 'agent' | 'project';
    /**
     * The SKILL.md file.
     */
    path: string;
    /**
     * The skill replaces a wider skill with the same name.
     */
    overrides: boolean;
    /**
     * Why the skill is not valid. The prompt does not list it.
     */
    error?: string;
};

/**
 * A remote Streamable HTTP declaration. It takes no headers or static tokens. The server decodes it strictly.
 *
 */
export type McpServerInput = {
    name: string;
    url: string;
    /**
     * Browser authorization. An empty object discovers the provider and registers a client.
     *
     */
    oauth?: {
        clientId?: string;
        /**
         * A vault:NAME reference. Dex rejects a secret value.
         */
        clientSecret?: string;
        scope?: string;
    };
};

/**
 * An MCP server from control storage. Plain environment and header values are not returned. Vault references are returned as written.
 *
 */
export type McpServer = {
    name: string;
    scope: IntegrationScope;
    /**
     * The server replaces a wider server with the same name.
     */
    overrides: boolean;
    /**
     * Absent for a bot entry that only turns off a global server.
     */
    transport?: 'stdio' | 'http';
    /**
     * idle means this view does not report a live connection.
     */
    state: 'idle' | 'connected' | 'failed' | 'disabled';
    /**
     * The MCP tool names. The bot gets each tool as mcp__<server>__<tool>.
     */
    tools: Array<string>;
    /**
     * The action or status of an OAuth connection. Absent for other connections.
     */
    oauth?: 'authorize' | 'reauthorize' | 'authorized';
    vaultReferences?: {
        env?: {
            [key: string]: string;
        };
        headers?: {
            [key: string]: string;
        };
    };
    error?: string;
};

