export type ChannelStatus = {
    state: 'off' | 'running' | 'error' | 'needs_login';
    reason?: string;
};

export type TelegramInput = {
    /**
     * Write-only. Empty keeps the saved token.
     */
    token: string;
    allowedUsers: Array<number>;
    options?: TelegramOptions;
    /**
     * Omission keeps the transport for the same bot. New bots default to polling.
     */
    transport?: 'polling' | 'webhook';
    webhook?: TelegramWebhookInput;
};

export type TelegramWebhookInput = {
    /**
     * Public HTTPS callback URL.
     */
    url: string;
};

export type TelegramOptions = {
    silent?: boolean;
    typing?: boolean;
    /**
     * Private chat status reactions. On when unset; false explicitly disables them.
     */
    reactions?: boolean;
    stt?: TelegramSpeechOptions;
};

export type TelegramSpeechOptions = {
    enabled?: boolean;
    /**
     * Explicit consent to send this bot's audio to the selected provider. The provider can be an external third party. No automatic fallback provider is used.
     */
    allowSending?: boolean;
    provider?: string;
    model?: string;
    language?: string;
    /**
     * Zero uses 30 seconds.
     */
    timeoutSeconds?: number;
    /**
     * Zero uses 20 MiB for input and response bytes.
     */
    maxBytes?: number;
    /**
     * Checks the audio duration that Telegram reports. Zero uses 300 seconds. dex does not decode audio to measure duration.
     */
    maxDurationSeconds?: number;
};

